        t.exec("goto-talkToUrhney", t.player.goto_tile, 3147, 3171, 0) -- the open ground south of the shed door
        pass_door("shedIn", "farming_shed_poordoor", "farming_shed_poordoor", 3147, 3172, 3147, 3172, 3147, 3173,
            function(tt) return tt.z >= 3173 end, "inside the shed, z >= 3173")
        -- Talk to Father Urhney, west of the Lumbridge Swamp.
        t.exec("talkToUrhney", t.player.talk_to, "father_urhney", 1)
        t.exec("talkToUrhney-dialog", t.chat.play, {
            "npc:Go away! I'm meditating!",
            "choose:Father Aereck sent me to talk to you.",
            "player:Father Aereck sent me to talk ",
            "npc:I suppose I'd better talk to y",
            "choose:He's got a ghost haunting his graveyard.",
            "player:He's got a ghost haunting his ",
            "npc:Oh, the silly fool.",
            "npc:I leave town for just five mon",
            "npc:(sigh)",
            "npc:Well, I can't go back and exor",
            "npc:Tell you what I can do though;",
            "mesbox:Father Urhney hands you an amu",
            "npc:It is an Amulet of Ghostspeak.",
            "npc:So called, because when you we",
            "npc:Maybe if you know what this ta",
